from __future__ import annotations
import argparse
from .common import record, run_purpose

PURPOSE = 'failure-analysis'
CATALOG = [{'id': 'fail-cache-stampede', 'concept': 'cache-expiry-stampede', 'domain': 'software-engineering', 'subdomain': 'caching', 'difficulty': 'advanced', 'question': 'A popular cache entry expires and backend traffic jumps by 100x even though request volume is unchanged. Explain the failure mode and what evidence would confirm it.', 'answer': "Many concurrent requests observe the same miss and independently regenerate the same value, creating a cache stampede. Confirm by correlating one key's expiry with a burst of identical backend work and many simultaneous cache misses. Mitigations include request coalescing/singleflight, soft expiration with background refresh, and jittered TTLs so many hot keys do not expire together. Simply increasing backend capacity leaves the synchronized miss behavior intact.", 'verification_details': 'Must identify synchronized regeneration after expiry, require per-key miss/backend evidence, and propose coalescing or staggered refresh rather than capacity-only mitigation.', 'tags': ['cache', 'stampede', 'ttl', 'backend-load'], 'verification_method': 'rubric'}, {'id': 'fail-sigpipe-write', 'concept': 'sigpipe-socket-write-process-exit', 'domain': 'systems-programming', 'subdomain': 'signals', 'difficulty': 'intermediate', 'question': 'A Unix server occasionally terminates while writing a response to a client that disconnected early. Logs end abruptly and the exit status indicates a signal. Explain a likely cause.', 'answer': "Writing to a closed pipe/socket can generate `SIGPIPE`. With the default disposition, that signal terminates the process before ordinary error handling logs the `EPIPE`. Confirm the terminating signal and the peer-close timing. Handle the condition using the platform's normal strategy—ignore/handle SIGPIPE process-wide where appropriate or use a send option that suppresses it—and then treat the failed write as an ordinary I/O error.", 'verification_details': 'Must connect peer-close writes with SIGPIPE/default termination, confirm via signal exit evidence, and convert the condition into ordinary EPIPE-style handling safely.', 'tags': ['sigpipe', 'socket', 'epipe', 'signals'], 'verification_method': 'rubric'}, {'id': 'fail-zombie-accumulation', 'concept': 'unreaped-child-zombie-accumulation', 'domain': 'operating-systems', 'subdomain': 'process-management', 'difficulty': 'intermediate', 'question': 'A long-running parent spawns short-lived helpers. Over time the process table fills with defunct children even though the helpers have exited. Explain the failure.', 'answer': "Exited children remain as zombies until the parent collects their termination status with a wait-family call (or uses an explicitly configured alternative lifecycle). The helper's resources are mostly released, but its process-table entry remains. Confirm with process state and parent PID, then fix the parent to reap children reliably, including concurrent exits and signal races. Killing zombie entries directly cannot work because the child is already dead; the parent must reap them or terminate so another reaper adopts them.", 'verification_details': 'Must identify missing wait/reaping, explain why zombies remain and cannot be killed directly, and require reliable child lifecycle handling.', 'tags': ['zombie', 'waitpid', 'process', 'reaping'], 'verification_method': 'rubric'}, {'id': 'fail-cow-memory-spike', 'concept': 'copy-on-write-fork-memory-spike', 'domain': 'operating-systems', 'subdomain': 'virtual-memory', 'difficulty': 'advanced', 'question': 'A large memory-resident process forks a worker. RSS initially looks cheap, but memory usage then surges as both processes continue modifying data. Explain why.', 'answer': 'After `fork()`, pages can initially be shared copy-on-write. When either process writes a shared page, the kernel creates a private copy for that process, so a write-heavy workload can rapidly destroy the sharing and approach the cost of two copies of the modified working set. Confirm with private-dirty/PSS-style metrics and fault activity rather than summing RSS blindly. Reduce post-fork mutation, fork before building the large mutable state, or use an IPC/shared-memory architecture designed for the workload.', 'verification_details': 'Must explain COW sharing followed by private copies on write, use appropriate memory-accounting evidence, and avoid assuming initial fork cost predicts steady-state memory.', 'tags': ['fork', 'copy-on-write', 'memory', 'rss'], 'verification_method': 'rubric'}, {'id': 'fail-unaligned-access', 'concept': 'unaligned-access-architecture-fault', 'domain': 'computer-architecture', 'subdomain': 'alignment', 'difficulty': 'advanced', 'question': 'Binary parsing code casts an arbitrary byte pointer to a wider integer pointer. It works on one CPU but faults on another architecture. Explain the portability failure.', 'answer': 'The pointer may not satisfy the alignment required by the wider type, and direct dereference can fault or have architecture/language-specific behavior. The cast can also violate aliasing/object-representation rules. Parse bytes explicitly or copy into a properly aligned object with a defined byte-order conversion. Confirm the failing address alignment and instruction/fault type. x86 tolerance for many unaligned accesses does not make the code portable.', 'verification_details': 'Must identify alignment and language-object issues, avoid raw wider dereference of arbitrary byte buffers, and propose byte-wise or memcpy-based decoding.', 'tags': ['alignment', 'binary-parser', 'portability', 'architecture'], 'verification_method': 'rubric'}, {'id': 'fail-inode-exhaustion', 'concept': 'filesystem-inode-exhaustion', 'domain': 'linux-infrastructure', 'subdomain': 'filesystems', 'difficulty': 'advanced', 'question': 'A filesystem reports plenty of free bytes, but applications fail to create new files with `ENOSPC`. The workload creates millions of tiny files. Explain the likely failure.', 'answer': 'The filesystem may have exhausted its available inode/object metadata capacity even though data blocks remain free. Check inode usage (and any filesystem-specific metadata limits), directory/file counts, and the exact mount/filesystem involved. Removing unused tiny files or choosing a layout/filesystem that supports the object count addresses the root cause. Adding block capacity alone may not help if the limiting metadata resource is unchanged.', 'verification_details': 'Must distinguish free data blocks from inode/metadata capacity, require filesystem-specific inode/object evidence, and avoid treating byte free space as sufficient.', 'tags': ['inode', 'enospc', 'filesystem', 'metadata'], 'verification_method': 'rubric'}, {'id': 'fail-stack-overflow-embedded', 'concept': 'embedded-stack-overflow-corruption', 'domain': 'embedded-systems', 'subdomain': 'memory-safety', 'difficulty': 'expert', 'question': 'An MCU resets or corrupts unrelated globals only in deeply nested error handling. Heap use is stable. Explain how stack exhaustion could produce these symptoms and how to verify it.', 'answer': 'Deep call chains, recursion, large automatic arrays, or interrupt nesting can push the stack beyond its reserved region. On small MCUs there may be no MMU guard page, so overflow can overwrite adjacent memory before a later crash/reset. Verify with stack high-water instrumentation/canaries, linker map bounds, worst-case call/interrupt depth, and debugger fault state. Move large buffers out of the stack, eliminate unbounded recursion, increase the region only with measured RAM budget, and configure hardware stack limits/MPU guards where available.', 'verification_details': 'Must connect deep automatic usage/nesting to unchecked stack growth, require high-water/bounds evidence, and propose bounded-stack or guard strategies.', 'tags': ['embedded', 'stack-overflow', 'mcu', 'memory-corruption'], 'verification_method': 'rubric'}, {'id': 'fail-tcp-zero-window', 'concept': 'tcp-zero-window-stall', 'domain': 'networking', 'subdomain': 'tcp-flow-control', 'difficulty': 'advanced', 'question': 'A TCP connection stays established but throughput drops to nearly zero. Packet captures show the receiver repeatedly advertising a zero window. Explain the failure.', 'answer': 'TCP flow control is stopping the sender because the receiver currently has no advertised receive-buffer space. The sender probes periodically but cannot resume normal transmission until the receiver opens its window. Investigate why the receiving application is not draining the socket, whether it is blocked downstream, and receive-buffer/memory pressure. This is different from congestion loss: the receiver is explicitly applying backpressure.', 'verification_details': 'Must identify receiver flow-control exhaustion from zero-window advertisements, distinguish it from congestion, and investigate application drain/buffer pressure.', 'tags': ['tcp', 'zero-window', 'flow-control', 'backpressure'], 'verification_method': 'rubric'}, {'id': 'fail-tombstone-resurrection', 'concept': 'distributed-tombstone-resurrection', 'domain': 'distributed-systems', 'subdomain': 'replication', 'difficulty': 'expert', 'question': 'A replicated eventually consistent store deletes a key with tombstones, but old values sometimes reappear after an offline replica rejoins long after tombstones were garbage-collected. Explain the failure.', 'answer': 'A replica that missed the deletion can retain an old live version. If all replicas that knew about the deletion garbage-collect the tombstone before the stale replica rejoins, reconciliation may see the old value without durable evidence that it was deleted and resurrect it. Safe tombstone GC therefore depends on repair/replication guarantees: retain deletion metadata long enough, ensure all replicas have observed it, use versioning/epochs, or rebuild stale replicas whose absence exceeded the safe window.', 'verification_details': 'Must explain loss of deletion evidence before stale replica repair, connect GC safety to anti-entropy/failure windows, and require a protocol ensuring deletion knowledge before removal.', 'tags': ['tombstone', 'eventual-consistency', 'replication', 'gc'], 'verification_method': 'rubric'}, {'id': 'fail-cuda-fork-context', 'concept': 'cuda-context-forked-process-failure', 'domain': 'compute-model-infrastructure', 'subdomain': 'multiprocessing', 'difficulty': 'expert', 'question': 'A Python data pipeline initializes CUDA in the parent and then forks worker processes. Workers later fail or hang when touching CUDA state inherited from the parent. Explain why this process model is unsafe.', 'answer': "A CUDA runtime/driver context is not generally safe to use after ordinary process `fork()` duplicates only the calling thread and copies complex runtime state without recreating the driver's internal process/thread machinery. The child inherits memory that looks initialized but not a valid independently initialized GPU runtime. Use a spawn-style process start method and initialize CUDA separately in each process that needs it, or keep worker processes CPU-only and communicate with a dedicated GPU process.", 'verification_details': 'Must identify inherited CUDA runtime/context state across fork as unsafe and require spawn/separate initialization or CPU-only workers.', 'tags': ['cuda', 'fork', 'multiprocessing', 'context'], 'verification_method': 'rubric'}]

FAMILIES = [
    {
        "id": x["id"],
        "concept": x["concept"],
        "domain": x["domain"],
    }
    for x in CATALOG
]
BY_ID = {x["id"]: x for x in CATALOG}

def build(family, rng, rid, _difficulty):
    x = BY_ID[family["id"]]
    return record(
        rid,
        x["domain"],
        x["subdomain"],
        PURPOSE,
        x["difficulty"],
        x["question"],
        x["answer"],
        x["verification_method"],
        x["verification_details"],
        x["tags"],
    )

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--records", type=int, default=len(FAMILIES))
    ap.add_argument("--seed", type=int, default=20260914)
    args = ap.parse_args()
    run_purpose(
        purpose=PURPOSE,
        families=FAMILIES,
        build=build,
        records_requested=args.records,
        seed=args.seed,
    )

if __name__ == "__main__":
    main()
